  font-family: var(--font-body);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow: hidden;
}

/* Container que simula tela vertical de smartphone no Desktop e tela cheia no Mobile */
#mobile-viewport {
