      let unmitigatedDmg = dmg;
      if (this.player.shield > 0) {
        if (unmitigatedDmg <= this.player.shield) {
          this.player.shield -= unmitigatedDmg;
          unmitigatedDmg = 0;
        } else {
          unmitigatedDmg -= this.player.shield;
          this.player.shield = 0;
