   ========================================================================== */

/* Topo: Status do Inimigo na Esquerda, Sprite de Corpo Inteiro na Direita */
.top-battle-row {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  width: 100%;
  z-index: 10;
  position: relative;
  gap: 8px;
  padding-top: 2px;
}

/* Superior Esquerdo: Caixa de Status do Inimigo */
.enemy-hud-box {
  flex: 1;
  max-width: 175px;
