  font-family: var(--font-title);
  font-size: 0.82rem;
  color: #fff;
  margin-bottom: 1px;
  line-height: 1.2;
}

.enemy-subname {
  display: block;
  font-size: 0.62rem;
  color: var(--text-muted);
  font-style: italic;
  margin-bottom: 5px;
}

.intent-badge {
  display: inline-flex;
