"/* Plataforma Pokémon do Monstro */
.pedestal-container {
  width: 165px;
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  z-index: 1;
}

.enemy-battle-pedestal {
  width: 100%;
  height: auto;
  object-fit: contain;
  /* Blur suave de profundidade de campo (Depth of Field) */
  filter: blur(0.75px) drop-shadow(0 6px 14px rgba(0, 0, 0, 0.85));
  animation: pedestalHover 5s infinite ease-in-out;
}

.pedestal-contact-shadow {
  width: 130px;
  height: 18px;
  background: radial-gradient(ellipse at center, rgba(0,0,0,0.92) 0%, rgba(0,0,0,0) 75%);
  border-radius: 50%;
  margin-top: -14px;
  filter: blur(1px);
}

/* Névoa Atmosférica Rasteira no Entorno da Plataforma */
.pedestal-mist-glow {
  position: absolute;
  bottom: -12px;
  left: 50%;
  transform: translateX(-50%);
  width: 210px;
  height: 42px;
  background: radial-gradient(ellipse at center, rgba(30, 75, 75, 0.5) 0%, rgba(14, 35, 38, 0.25) 55%, rgba(0, 0, 0, 0) 80%);
  filter: blur(8px);
  pointer-events: none;
  z-index: 0;
  animation: mistPulse 4s infinite alternate ease-in-out;
}

@keyframes mistPulse {
  0% { transform: translateX(-50%) scale(0.96); opacity: 0.7; }
  100% { transform: translateX(-50%) scale(1.06); opacity: 1; }
}

@keyframes idleEnemyBreathing {
  0%, 100% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-4px) scale(1.02); }
}

@keyframes pedestalHover {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-3px); }
}"

