".player-bust-sprite {
  height: 265px; /* Ampliado para preencher o canto inferior com destaque */
  width: auto;
  max-width: 190px;
  object-fit: contain;
  object-position: bottom left;
  filter: drop-shadow(0 14px 24px rgba(0, 0, 0, 0.95));
  user-select: none;
  pointer-events: none;
  margin-bottom: -16px;
  margin-left: -12px;
  transform-origin: bottom center;
}

.player-bust-sprite.hidden-sprite {
  display: none !important;
}

.player-bust-sprite.active-idle {
  display: block;
  animation: idleBreathing 3.5s infinite ease-in-out;
}

/* Animação Cômica de Ataque Aristocrático (Estalo de dedos + Impulso Ostentador) */
@keyframes comicAristocratAttack {
  0% {
    transform: translate(0, 0) scale(1) rotate(0deg);
    filter: drop-shadow(0 14px 24px rgba(0,0,0,0.95));
  }
  25% {
    /* Avanço presunçoso e ostentador */
    transform: translate(28px, -18px) scale(1.1) rotate(5deg);
    filter: drop-shadow(0 0 25px rgba(241, 196, 15, 0.85)) brightness(1.3);
  }
  50% {
    /* Clímax do estalo de ouro */
    transform: translate(32px, -20px) scale(1.12) rotate(4deg);
    filter: drop-shadow(0 0 35px rgba(255, 215, 0, 0.95)) brightness(1.4);
  }
  75% {
    transform: translate(16px, -10px) scale(1.05) rotate(2deg);
    filter: drop-shadow(0 0 18px rgba(241, 196, 15, 0.6)) brightness(1.15);
  }
  100% {
    transform: translate(0, 0) scale(1) rotate(0deg);
    filter: drop-shadow(0 14px 24px rgba(0,0,0,0.95));
  }
}

.player-bust-sprite.active-attack {
  display: block;
  animation: comicAristocratAttack 0.65s cubic-bezier(0.2, 0.85, 0.3, 1.1) forwards;
}

/* Animação Cômica de Dano Histérico (Escândalo do Herdeiro e Vinho Voando) */
