    transform: translate(0, 0) scale(1) rotate(0deg);
    filter: brightness(1);
  }
  12% {
    /* Tranco violento para trás em choque */
    transform: translate(-34px, 14px) scale(0.9) rotate(-14deg);
    filter: brightness(2) drop-shadow(0 0 25px #ff4757);
  }
