"/* Inferior Direito: Coluna de Ações & Cartas */
.battle-actions-column {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}

.actions-subfooter {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  margin-top: 4px;
  padding: 0 4px;
}

/* Botão Finalizar Turno Compacto Estilo Hades */
.btn-end-turn-styled {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  background: linear-gradient(180deg, #2b253b 0%, #151320 100%);
  border: 1.5px solid #d4af37;
  border-radius: 20px;
  padding: 4px 12px;
  color: #f1f2f6;
  cursor: pointer;
  box-shadow: 
    0 3px 8px rgba(0, 0, 0, 0.75),
    inset 0 1px 1px rgba(255, 255, 255, 0.25),
    inset 0 0 6px rgba(0, 0, 0, 0.6);
  transition: transform 0.15s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.15s, filter 0.15s;
  user-select: none;
}

.btn-end-turn-styled:hover {
  transform: translateY(-2px) scale(1.03);
  filter: brightness(1.15);
  box-shadow: 0 5px 14px rgba(0, 0, 0, 0.9), 0 0 12px rgba(212, 175, 55, 0.45);
}

.btn-end-turn-styled:active {
  transform: translateY(1px) scale(0.96);
  box-shadow: 0 1px 4px rgba(0, 0, 0, 0.9);
}

.btn-turn-icon {
  font-size: 0.75rem;
  line-height: 1;
}

.btn-turn-text {
  font-size: 0.64rem;
  font-family: var(--font-title);
  font-weight: 700;
  letter-spacing: 0.5px;
  color: #f5eedc;
  text-transform: lowercase;
  text-shadow: 0 1px 3px rgba(0, 0, 0, 0.9);
}"

