"/* Moldura e Frame de Carta Mitológica Oficial / Hades Style */
.game-card {
  width: 72px;
  height: 114px;
  background: #14121d;
  border-radius: 6px;
  position: relative;
  cursor: pointer;
  flex-shrink: 0;
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.85);
