.cards-hand-container {
  display: flex;
  align-items: flex-end;
  justify-content: center;
  min-height: 130px;
  max-height: 140px;
  overflow: visible !important;
  padding: 12px 6px 4px;
  position: relative;
  z-index: 10;
}

/* Moldura e Frame de Carta Mitológica Oficial em Leque / Hearthstone Arc */
.game-card {
  width: 74px;
  height: 118px;
  background: #14121d;
  border-radius: 6px;
  position: relative;
  cursor: pointer;
  flex-shrink: 0;
  margin-left: -24px; /* Sobreposição em leque estilo Hearthstone que poupa largura */
  box-shadow: 0 6px 14px rgba(0, 0, 0, 0.85);
  transform: translateY(var(--card-y, 0px)) rotate(var(--card-rot, 0deg));
  transform-origin: 50% 120%; /* Ponto pivô do leque na base da mão */
  z-index: var(--card-z, 1);
  transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275), box-shadow 0.22s, filter 0.2s;
  user-select: none;
  overflow: visible;
}

.game-card:first-child {
  margin-left: 0;
}"

