.comic-viewer-box {
  width: 92%;
  max-width: 390px;
  max-height: 90vh;
  background: #0f0c18;
  border: 2px solid var(--border-gold);
  border-radius: 14px;
  box-shadow: 0 0 40px rgba(0, 0, 0, 0.95), 0 0 20px rgba(229, 185, 95, 0.3);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: zoomPop 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.comic-viewer-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 12px;
  background: rgba(20, 16, 32, 0.95);
  border-bottom: 1px solid rgba(229, 185, 95, 0.3);
}

.comic-chapter-tag {
  font-family: var(--font-title);
  font-size: 0.7rem;
  font-weight: 800;
  color: #f1c40f;
  letter-spacing: 0.5px;
}

.comic-btn-close {
  background: none;
  border: none;
  color: #fff;
  font-size: 1.1rem;
  font-weight: 800;
  cursor: pointer;
  padding: 2px 6px;
  border-radius: 4px;
  transition: background 0.15s, color 0.15s;
}

.comic-btn-close:hover {
  background: rgba(255, 71, 87, 0.3);
  color: #ff4757;
}

.comic-stage {
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 10px;
  background: #08060d;
  flex: 1;
  overflow-y: auto;
}

.comic-panel-container {
  width: 100%;
  aspect-ratio: 4 / 3;
  max-height: 250px;
  border: 2px solid rgba(229, 185, 95, 0.4);
  border-radius: 8px;
  overflow: hidden;
  background: #141020;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.85);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
