/* ==========================================================================
   BANNER CINEMATOGRÁFICO DE TRANSIÇÃO DE FASE / SALA (HADES STYLE)
   ========================================================================== */
.phase-transition-overlay {
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at center, rgba(30, 15, 45, 0.96) 0%, rgba(8, 6, 12, 0.98) 85%);
  backdrop-filter: blur(8px);
  display: flex;
  justify-content: center;
  align-items: center;
  z-index: 300;
  animation: phaseFadeIn 0.35s ease-out;
}

@keyframes phaseFadeIn {
  from { opacity: 0; transform: scale(1.05); }
  to { opacity: 1; transform: scale(1); }
}

.phase-transition-content {
  text-align: center;
  padding: 24px;
  max-width: 360px;
  animation: zoomPop 0.4s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}

.phase-transition-sub {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 2px;
  color: #ffd700;
  text-shadow: 0 0 12px rgba(255, 215, 0, 0.8);
  display: block;
  margin-bottom: 6px;
  text-transform: uppercase;
}

.phase-transition-content h1 {
  font-family: var(--font-title);
  font-size: 1.35rem;
  font-weight: 900;
  color: #fffaf0;
  margin: 0 0 8px;
  letter-spacing: 1px;
  text-shadow: 0 3px 10px rgba(0, 0, 0, 0.9), 0 0 20px rgba(229, 185, 95, 0.5);
}

.phase-divider {
  color: #ffd700;
  font-size: 0.8rem;
  letter-spacing: 4px;
  margin: 6px 0 10px;
  text-shadow: 0 0 10px #ffd700;
}

.phase-transition-content p {
  font-size: 0.78rem;
  line-height: 1.4;
  color: #dfe4ea;
  font-style: italic;
  margin: 0;
}

/* ==========================================================================
   TELA DE BÊNÇÃO DOS DEUSES DO OLIMPO (HADES STYLE BOON SELECTION)
   ========================================================================== */
