  align-items: center;
  gap: 4px;
  white-space: nowrap;
  transition: transform 0.15s, box-shadow 0.15s, background 0.15s;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.7);
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}

