"/* Nós de Câmaras no Mapa: Waypoints Sleek e Translúcidos (Sem cobrir o pergaminho) */
.map-node {
  position: absolute;
  transform: translate(-50%, -50%);
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: rgba(20, 15, 30, 0.7);
  border: 2px solid #a4b0be;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: transform 0.25s cubic-bezier(0.175, 0.885, 0.32, 1.275), border-color 0.25s, box-shadow 0.25s;
  z-index: 10;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.8);
}

.map-node:hover {
  transform: translate(-50%, -50%) scale(1.35);
}

.node-ring {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #a4b0be;
  transition: background 0.3s, box-shadow 0.3s;
}

.map-node.active-node {
  border-color: #ffd700;
  background: rgba(255, 215, 0, 0.25);
  box-shadow: 0 0 16px rgba(255, 215, 0, 0.95), 0 0 6px #ffd700;
  transform: translate(-50%, -50%) scale(1.25);
  animation: nodeActivePulse 1.8s infinite ease-in-out;
}

.map-node.active-node .node-ring {
  background: #ffd700;
  box-shadow: 0 0 8px #ffd700;
}

@keyframes nodeActivePulse {
  0%, 100% { box-shadow: 0 0 12px rgba(255, 215, 0, 0.8), 0 0 4px #ffd700; }
  50% { box-shadow: 0 0 22px rgba(255, 215, 0, 1), 0 0 10px #ffd700; }
}

.map-node.completed-node {
  border-color: #2ed573;
  background: rgba(46, 213, 115, 0.2);
  box-shadow: 0 0 10px rgba(46, 213, 115, 0.8);
}

