        <img src="${b.icon}" class="blessing-chip-icon" alt="${b.name}">
        <span>${b.shortLabel}</span>
      `;
      chip.addEventListener('click', () => {
        this.activateBlessing(blessingId);
      });
      bar.appendChild(chip);
    });
  }
"

