args.CommandLine:
"python -c "
with open('src/game.js', 'r', encoding='utf-8') as f:
    code = f.read()

stack = []
in_str = None
escape = False
in_line_comment = False
in_block_comment = False

lines = code.split('\n')
for line_no, line in enumerate(lines, 1):
    i = 0
    while i < len(line):
        ch = line[i]
        nxt = line[i+1] if i + 1 < len(line) else ''

        if in_line_comment:
            break
        if in_block_comment:
            if ch == '*' and nxt == '/':
                in_block_comment = False
                i += 1
            i += 1
            continue

        if in_str:
            if escape:
                escape = False
            elif ch == '\\\\':
                escape = True
            elif ch == in_str:
                in_str = None
            i += 1
            continue

        if ch == '/' and nxt == '/':
            break
        if ch == '/' and nxt == '*':
            in_block_comment = True
            i += 1
            i += 1
            continue

        if ch in ('\'', '\"', '\`'):
            in_str = ch
            i += 1
            continue

        if ch in '({[':
            stack.append((ch, line_no, i+1))
        elif ch in ')}]':
            if not stack:
                print(f'Unmatched closing {ch} at line {line_no}:{i+1}')
            else:
                last, l_no, c_no = stack.pop()
                expected = {')':'(', '}':'{', ']':'['}[ch]
                if last != expected:
                    print(f'Mismatched {ch} at line {line_no}:{i+1}, expected {expected} from line {l_no}:{c_no}')
        i += 1
    in_line_comment = False

if stack:
    print(f'Unclosed items remaining: {len(stack)}')
else:
    print('ALL SYNTAX BALANCED AND VERIFIED!')
""

