"@keyframes cardSlamTable {
  0% {
    transform: scale(2.05) translateY(-38px) rotate(-6deg);
    filter: brightness(1.7) drop-shadow(0 20px 25px rgba(0, 0, 0, 0.95));
    opacity: 0.8;
  }
  45% {
    transform: scale(0.86) translateY(4px) rotate(2deg);
    filter: brightness(1.2) drop-shadow(0 4px 8px rgba(0, 0, 0, 0.8));
    opacity: 1;
  }
  75% {
    transform: scale(1.08) translateY(-2px) rotate(-0.5deg);
  }
  100% {
    transform: scale(1) translateY(0) rotate(0deg);
    filter: brightness(1);
    opacity: 1;
  }
}

.table-played-slot.card-slam-anim,
.mini-playing-card.card-slam-anim {
  animation: cardSlamTable 0.38s cubic-bezier(0.16, 0.9, 0.28, 1.3) both !important;
  z-index: 60 !important;
}

@keyframes feltImpactWave {
  0% {
    box-shadow: 0 0 0 0 rgba(255, 215, 0, 0.95), inset 0 0 16px rgba(255, 215, 0, 0.6);
    opacity: 1;
  }
  50% {
    box-shadow: 0 0 0 18px rgba(255, 215, 0, 0.35), inset 0 0 6px rgba(255, 215, 0, 0.3);
    opacity: 0.8;
  }
  100% {
    box-shadow: 0 0 0 28px rgba(255, 215, 0, 0), inset 0 0 0 rgba(255, 215, 0, 0);
    opacity: 0;
  }
}

.table-played-slot.slam-impact::after {
  content: '';
  position: absolute;
  inset: -6px;
  border-radius: 10px;
  border: 2px solid #ffd700;
  pointer-events: none;
  animation: feltImpactWave 0.45s ease-out forwards;
}

@keyframes tableFeltShake {
  0% { transform: translateY(0); }
  25% { transform: translateY(3.5px); }
  50% { transform: translateY(-2.5px); }
  75% { transform: translateY(1.5px); }
  100% { transform: translateY(0); }
}

.truco-felt-surface.felt-bump {
  animation: tableFeltShake 0.24s ease-out both;
}"

