    def __init__(self):
        super().__init__()
        self.stack = []
        self.void_tags = {'meta', 'link', 'img', 'br', 'hr', 'input', 'source'}
    def handle_starttag(self, tag, attrs):
        if tag not in self.void_tags:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in self.void_tags:
            if not self.stack:
                print('Extra closing tag:', tag)
